"""Substitute current memory values into response templates."""

from __future__ import annotations

import re
from typing import TYPE_CHECKING

import structlog

from rasa.mantle.content.responses import ResponseButton
from rasa.mantle.default_skills import (
    DEFAULT_CONTINUE_INTERRUPTED,
    INTERRUPTED_TASK_NAME_ENTRY,
    INTERRUPTED_TASK_NAME_FALLBACK,
)

if TYPE_CHECKING:
    from rasa.mantle.memory.manager import MemoryManager
    from rasa.mantle.state.tracker_handle import TrackerHandle

structlogger = structlog.get_logger()

# Session and bare placeholders in one pattern; only the original *template* is
# scanned so substituted values cannot introduce new placeholders.
_PLACEHOLDER_RE = re.compile(
    r"\{session\.([^}]+)\}|\{([A-Za-z_]\w*)\}",
    re.ASCII,
)
_INTERRUPTED_TASK_NAME_SLOT = (
    f"{DEFAULT_CONTINUE_INTERRUPTED}.{INTERRUPTED_TASK_NAME_ENTRY}"
)


def substitute_memory_placeholders(template: str, tracker_handle: TrackerHandle) -> str:
    """Replace memory placeholders in *template* with current values.

    Matches ``{session.<namespace>.<entry>}`` and bare ``{entry}`` names in a
    single pass over *template* only. Resolved values are inserted verbatim and
    are never re-scanned, so user-controlled memory cannot inject additional
    placeholders into the output.

    Missing, denied, or unset values leave the placeholder unchanged and log
    a warning — except for
    ``default_continue_interrupted.interrupted_task_name``, which falls back
    to a generic label so resume prompts never leak raw placeholders.
    """
    memory = tracker_handle.memory
    skill_id, flow_id = tracker_handle.memory_scope()
    memory_values = {
        name: entry.value for name, entry in memory.read_all(skill_id, flow_id).items()
    }

    parts: list[str] = []
    last_end = 0
    for match in _PLACEHOLDER_RE.finditer(template):
        parts.append(template[last_end : match.start()])
        parts.append(
            _resolve_memory_placeholder(match, memory, skill_id, flow_id, memory_values)
        )
        last_end = match.end()
    parts.append(template[last_end:])
    return "".join(parts)


def _resolve_memory_placeholder(
    match: re.Match[str],
    memory: MemoryManager,
    skill_id: str,
    flow_id: str,
    memory_values: dict[str, object],
) -> str:
    session_ref = match.group(1)
    if session_ref is not None:
        return _resolve_session_slot(match, session_ref, memory_values)

    entry_name = match.group(2)
    return _resolve_bare_entry(match, entry_name, memory, skill_id, flow_id)


def _resolve_session_slot(
    match: re.Match[str],
    ref: str,
    memory_values: dict[str, object],
) -> str:
    if "." not in ref:
        structlogger.warning(
            "mantle.skill_executor.utterance.unqualified_slot",
            slot_name=ref,
            placeholder=match.group(0),
        )
        return match.group(0)

    value = memory_values.get(ref)
    if value is None:
        if ref == _INTERRUPTED_TASK_NAME_SLOT:
            structlogger.warning(
                "mantle.skill_executor.utterance.missing_interrupted_task_name",
                slot_name=ref,
                placeholder=match.group(0),
            )
            return INTERRUPTED_TASK_NAME_FALLBACK
        structlogger.warning(
            "mantle.skill_executor.utterance.missing_slot",
            slot_name=ref,
            placeholder=match.group(0),
        )
        return match.group(0)
    return str(value)


def _resolve_bare_entry(
    match: re.Match[str],
    entry_name: str,
    memory: MemoryManager,
    skill_id: str,
    flow_id: str,
) -> str:
    try:
        entry = memory.get(skill_id, flow_id, entry_name)
    except ValueError:
        structlogger.warning(
            "mantle.skill_executor.utterance.bare_entry_resolve_failed",
            entry_name=entry_name,
            placeholder=match.group(0),
        )
        return match.group(0)
    if entry is None:
        structlogger.warning(
            "mantle.skill_executor.utterance.bare_entry_denied",
            entry_name=entry_name,
            placeholder=match.group(0),
        )
        return match.group(0)
    if entry.value is None:
        structlogger.warning(
            "mantle.skill_executor.utterance.bare_entry_unset",
            entry_name=entry_name,
            placeholder=match.group(0),
        )
        return match.group(0)
    return str(entry.value)


def resolve_response_buttons(
    buttons: tuple[ResponseButton, ...],
    tracker_handle: TrackerHandle,
) -> tuple[ResponseButton, ...]:
    """Substitute memory placeholders in button titles and payloads.

    Omitted payloads are filled from the resolved title so channels always
    receive a payload string.
    """
    resolved: list[ResponseButton] = []
    for button in buttons:
        title = substitute_memory_placeholders(button.title, tracker_handle)
        payload = (
            title
            if button.payload is None
            else substitute_memory_placeholders(button.payload, tracker_handle)
        )
        resolved.append(ResponseButton(title=title, payload=payload))
    return tuple(resolved)
